class Solution {
public:
    vector<int> findDiagonalOrder(vector<vector<int>>& mat) {
        if (mat.empty() || mat[0].empty()) return {};
        int m = mat.size(), n = mat[0].size();
        vector<vector<int>> diagonals(m + n - 1);
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                diagonals[r + c].push_back(mat[r][c]);
            }
        }
        vector<int> res;
        for (int d = 0; d < m + n - 1; ++d) {
            if (d % 2 == 0) {
                reverse(diagonals[d].begin(), diagonals[d].end());
            }
            res.insert(res.end(), diagonals[d].begin(), diagonals[d].end());
        }
        return res;
    }
};

class Solution {
    public int[] findDiagonalOrder(int[][] mat) {
        if (mat == null || mat.length == 0) return new int[0];
        int m = mat.length, n = mat[0].length;
        List<List<Integer>> diagonals = new ArrayList<>();
        for (int i = 0; i < m + n - 1; i++) diagonals.add(new ArrayList<>());
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                diagonals.get(r + c).add(mat[r][c]);
            }
        }
        int[] res = new int[m * n];
        int idx = 0;
        for (int d = 0; d < m + n - 1; d++) {
            List<Integer> diag = diagonals.get(d);
            if (d % 2 == 0) {
                for (int i = diag.size() - 1; i >= 0; i--) res[idx++] = diag.get(i);
            } else {
                for (int i = 0; i < diag.size(); i++) res[idx++] = diag.get(i);
            }
        }
        return res;
    }
}

var findDiagonalOrder = function(mat) {
    if (!mat || mat.length === 0 || mat[0].length === 0) return [];
    const m = mat.length, n = mat[0].length;
    const diagonals = Array.from({ length: m + n - 1 }, () => []);
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            diagonals[r + c].push(mat[r][c]);
        }
    }
    const res = [];
    for (let d = 0; d < m + n - 1; d++) {
        if (d % 2 === 0) {
            res.push(...diagonals[d].reverse());
        } else {
            res.push(...diagonals[d]);
        }
    }
    return res;
};
